// Fallback guidance from a generator's goal if it isn't in the map above.
function deliversFromGoal(key) {
  const goal = GENERATOR_DEFINITIONS[key] && GENERATOR_DEFINITIONS[key].goal;
  if (!goal) return "";
  const stripped = goal.replace(
    /^(Create|Write|Build|Plan|Summarize|Position|Optimize|Turn)\s+(a |an |the )?/i,
    ""
  );
  return stripped.charAt(0).toUpperCase() + stripped.slice(1) + ".";
}

function infoIconHtml(text) {
  // A span (not a button) so heading/button CSS rules don't override its size.
  return `<span class="info-i" role="button" tabindex="0" aria-label="More info" title="${escapeHtml(
    text
  )}">i</span>`;
}

function annotateGenerators() {
  document.querySelectorAll(".generator-card").forEach((card) => {
    if (card.dataset.annotated === "true") {
      return;
    }

    const input = card.querySelector("input[data-generator-key]");
    const nameSpan = card.querySelector("span");

    if (!input || !nameSpan) {
      return;
    }

    const key = input.dataset.generatorKey;
    const info = GENERATOR_DELIVERS[key] || deliversFromGoal(key);

    if (info && !card.querySelector(".generator-card__delivers")) {
      const col = document.createElement("span");
      col.className = "generator-card__text";
      nameSpan.classList.add("generator-card__name");
      nameSpan.replaceWith(col);
      col.appendChild(nameSpan);

      const sub = document.createElement("span");
      sub.className = "generator-card__delivers";
      sub.textContent = info;
      col.appendChild(sub);
    }

    card.dataset.annotated = "true";
  });

  Object.keys(SECTION_INFO).forEach((id) => {
    const heading = getElement(id);

    if (heading && !heading.querySelector(".info-i")) {
      heading.insertAdjacentHTML("beforeend", " " + infoIconHtml(SECTION_INFO[id]));
    }
  });

  document.querySelectorAll(".premium-panel").forEach((panel) => {
    const key = panel.dataset.premiumPanel;
    const h3 = panel.querySelector("h3");

    if (h3 && key && PREMIUM_INFO[key] && !h3.querySelector(".info-i")) {
      h3.insertAdjacentHTML("beforeend", " " + infoIconHtml(PREMIUM_INFO[key]));
    }
  });
}

// Make ⓘ icons tap-friendly: native title only shows on hover (no touch),
// so on click show a small popover with the same text (toggles / dismisses).
function initInfoPopovers() {
  document.addEventListener("click", (event) => {
    const icon = event.target.closest(".info-i");
    const openPop = document.querySelector(".info-pop");
    const clickedOpenIcon = openPop && icon && icon.contains(openPop);

    document.querySelectorAll(".info-pop").forEach((pop) => pop.remove());

    if (!icon || clickedOpenIcon) {
      return;
    }

    const text = icon.getAttribute("title");
    if (!text) return;

    const pop = document.createElement("span");
    pop.className = "info-pop";
    pop.textContent = text;
    icon.appendChild(pop);
  });
}

// Confetti burst for milestone moments (100% readiness, first generate).
// Appends inside #p2p-haus-app when embedded (so the scoped CSS applies),
// else document.body. Skipped under prefers-reduced-motion.
function celebrate() {
  if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
    return;
  }

  const host = document.getElementById("p2p-haus-app") || document.body;
  const colors = ["#27ae6e", "#0d7377", "#2563eb", "#5b3c8c", "#d6336c", "#c9a84c"];
  const layer = document.createElement("div");
  layer.className = "confetti-layer";

  for (let i = 0; i < 60; i += 1) {
    const piece = document.createElement("span");
    piece.className = "confetti-piece";
    piece.style.left = Math.random() * 100 + "vw";
    piece.style.background = colors[i % colors.length];
    piece.style.animationDelay = Math.random() * 0.5 + "s";
    piece.style.animationDuration = 2 + Math.random() * 1.6 + "s";
    piece.style.setProperty("--spin", Math.round(Math.random() * 720 + 360) + "deg");
    layer.appendChild(piece);
  }

  host.appendChild(layer);
  setTimeout(() => layer.remove(), 4400);
}

// JS-driven sticky for the "Your Pack" rail. position:sticky can silently
// break inside some Shopify theme wrappers (an ancestor with overflow or a
// transform), so pin the rail with position:fixed over its reserved 320px
// grid column instead — which survives those wrappers. Degrades safely to
// normal flow on error or on the stacked (<=980px) layout.
function initStickyRail() {
  const rail = document.querySelector(".build-rail");
  const pinned = document.querySelector(".build-rail__pinned");
  const layout = document.querySelector(".build-layout");
  if (!rail || !pinned || !layout) return;

  const RAIL_WIDTH = 320; // matches .build-layout's grid track
  let ticking = false;

  const stickyOffset = () => {
    const host = document.getElementById("p2p-haus-app") || document.documentElement;
    const n = parseInt(getComputedStyle(host).getPropertyValue("--rail-sticky-top"), 10);
    return Number.isFinite(n) ? n : 20;
  };

  const clearPin = () => {
    pinned.style.position = "";
    pinned.style.top = "";
    pinned.style.left = "";
    pinned.style.width = "";
    rail.style.paddingTop = "";
  };

  const update = () => {
    ticking = false;
    try {
      if (window.innerWidth <= 980) {
        clearPin();
        return;
      }
      const off = stickyOffset();
      const railRect = rail.getBoundingClientRect();

      if (railRect.top >= off) {
        clearPin();
      } else {
        // Pin only the progress widget; reserve its height with padding on the
        // rail so the scrolling extras block below doesn't jump up.
        const pinnedH = pinned.offsetHeight;
        pinned.style.position = "fixed";
        pinned.style.top = off + "px";
        pinned.style.left = Math.round(railRect.right - RAIL_WIDTH) + "px";
        pinned.style.width = RAIL_WIDTH + "px";
        rail.style.paddingTop = pinnedH + "px";
      }
    } catch (err) {
      clearPin();
    }
  };

  const onScroll = () => {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(update);
    }
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  window.addEventListener("resize", update, { passive: true });
  update();
}

